  // ===================================================================
  // ★2. UIクリーンアップ処理：
  //   ① WhatsIndo 横の「全～～問」バッジを完全非表示化
  //   ② 文脈下線モードの「文脈下線＋単語和訳」ボタンを消去（2ボタン化）
  // ===================================================================
  function applyRequestedCleanups() {
    // ① 「全4,064問」などの総問題数バッジを非表示化
    document.querySelectorAll('span, div, b, strong, small').forEach(el => {
      if (el.children.length === 0) {
        const txt = (el.textContent || '').replace(/\s+/g, '');
        if (/^全[\d,]+問$/.test(txt)) {
          el.style.setProperty('display', 'none', 'important');
          if (el.parentElement && el.parentElement.children.length === 1 && el.parentElement.tagName !== 'HEADER') {
            el.parentElement.style.setProperty('display', 'none', 'important');
          }
        }
      }
    });

    // ② 文脈下線モードの「文脈下線＋単語和訳」ボタンを消去し、「文脈下線のみ」をデフォルト選択にする
    document.querySelectorAll('button, .sub-btn, .chip, .filter-btn, span, label').forEach(el => {
      const txt = (el.textContent || '').trim();
      if ((txt.includes('文脈') && txt.includes('単語') && (txt.includes('＋') || txt.includes('+'))) || txt === '文脈下線＋単語和訳') {
        const wasActive = el.classList.contains('active') || el.getAttribute('aria-pressed') === 'true';
        el.style.setProperty('display', 'none', 'important');
        if (wasActive && el.parentElement) {
          const contextOnlyBtn = Array.from(el.parentElement.children).find(sib =>
            sib !== el && (sib.textContent || '').includes('文脈下線のみ')
          );
          if (contextOnlyBtn) contextOnlyBtn.click();
        }
      }
    });
  }

  // ===================================================================
  // ★3. WhatsApp風「日常ストーリー（Status Harian）」UI＆クイズエンジン注入
