  function deepRepairValue(val) {
    if (typeof val === "string") {
      let s = val;
      for (let i = 0; i < REPAIR_PAIRS.length; i++) {
        if (s.includes(REPAIR_PAIRS[i][0])) {
          s = s.split(REPAIR_PAIRS[i][0]).join(REPAIR_PAIRS[i][1]);
        }
      }
      // 万が一残っているキリル・アラビア・ハングル文字も安全に除去
      s = s.replace(/[\u0400-\u04FF\u0600-\u06FF\uAC00-\uD7AF]+/g, "");
      return s;
    }
    if (Array.isArray(val)) {
      for (let i = 0; i < val.length; i++) {
        val[i] = deepRepairValue(val[i]);
      }
      return val;
    }
    if (val && typeof val === "object") {
      Object.keys(val).forEach(k => {
        val[k] = deepRepairValue(val[k]);
      });
      return val;
    }
    return val;
  }

