  function detectCategory(item) {
    const text = `${item.m || ""} ${item.tr || ""} ${item.note || ""}`;
    for (let i = 0; i < TOPIC_RULES.length; i++) {
      if (TOPIC_RULES[i].re.test(text)) {
        return TOPIC_RULES[i].id;
      }
    }
    return "🏠 日常・生活・移動";
  }

  // 重複排除＋全単語への分野タグ自動付与（検索＆解説表示用）
  const uniqueVocabMap = new Map();
  d.vocab.forEach(item => {
    if (!item || !item.w) return;
    ["w", "r", "m", "ex", "tr", "note"].forEach(k => {
      if (typeof item[k] === "string") {
        item[k] = item[k].replace(/\[cite:\s*[\d,\s]+\]/gi, "").trim();
      }
    });
    const cat = detectCategory(item);
    item.topicCat = cat;
    if (item.note && !item.note.startsWith("【分野：")) {
      item.note = `【分野：${cat}】 ${item.note}`;
    } else if (!item.note) {
      item.note = `【分野：${cat}】`;
    }
    const key = `${item.p || 'other'}::${item.w.trim().toLowerCase()}`;
    uniqueVocabMap.set(key, item);
  });
  d.vocab = Array.from(uniqueVocabMap.values());

  if (typeof window.loadAllData === "function") {
    window.loadAllData();
  }

