  const rawVocabArr = d.vocab;
  const rawAcroArr  = d.acro;

  const vKeySet = new Set(rawVocabArr.map(x => `${x.p || 'other'}::${(x.w || '').trim().toLowerCase()}`));
  batch21Vocab.forEach(item => {
    const k = `${item.p || 'other'}::${item.w.trim().toLowerCase()}`;
    if (!vKeySet.has(k)) {
      rawVocabArr.push(item);
      vKeySet.add(k);
    }
  });

  const aKeySet = new Set(rawAcroArr.map(x => (x.acro || '').trim().toLowerCase()));
  batch21Acro.forEach(item => {
    const k = item.acro.trim().toLowerCase();
    if (!aKeySet.has(k)) {
      rawAcroArr.push(item);
      aKeySet.add(k);
    }
  });

