  //    待ち時間ゼロ（0.000秒）でその場で即座に同期実行させるインターセプター！
  // -------------------------------------------------------------------
  const origSetTimeout = window.setTimeout;
  window.setTimeout = function(fn, delay) {
    if (typeof fn === "function" && (delay === 10 || delay === 25)) {
      try { fn(); } catch (e) {}
      return 0;
    }
    return origSetTimeout.apply(this, arguments);
  };

  // -------------------------------------------------------------------
