  // -------------------------------------------------------------------
  // 3. ★同期フェーズ（0.000秒）での完全統合！
  //    d.vocab（および DB.vocab）にステップ1・ステップ2・V8のすべてを即座に反映！
  // -------------------------------------------------------------------
  function synchronizeAllVocabImmediately() {
    const rawVocab = d.vocab;
    const dbVocab  = (typeof DB !== "undefined" && DB && Array.isArray(DB.vocab)) ? DB.vocab : null;

    [rawVocab, dbVocab].forEach(arr => {
      if (!Array.isArray(arr)) return;
      const mapByW = new Map();

      for (let i = 0; i < arr.length; i++) {
        const item = arr[i];
        if (!item || !item.w) continue;
        const wLow = item.w.trim().toLowerCase();
        if (mapByW.has(wLow)) {
          const prev = mapByW.get(wLow);
          if ((item.note || "").length >= (prev.note || "").length) {
            Object.assign(prev, item);
          }
          item.__dupRemoveV8 = true;
        } else {
          mapByW.set(wLow, item);
        }
      }

      for (let i = arr.length - 1; i >= 0; i--) {
        if (arr[i] && arr[i].__dupRemoveV8) arr.splice(i, 1);
      }

      V8_CORE_DAILY_WORDS.forEach(wObj => {
        const wLow = wObj.w.trim().toLowerCase();
        if (mapByW.has(wLow)) {
          const ex = mapByW.get(wLow);
          if ((wObj.note || "").length >= (ex.note || "").length) {
            Object.assign(ex, wObj);
            if (ex.fullM !== undefined) ex.fullM = wObj.m;
            if (ex.cleanM !== undefined && typeof cleanChoiceMeaning === "function") {
              ex.cleanM = cleanChoiceMeaning(wObj.m);
            }
          }
        } else {
          const copy = { ...wObj };
          if (arr === dbVocab || typeof cleanChoiceMeaning === "function") {
            copy.fullM = wObj.m;
            copy.cleanM = typeof cleanChoiceMeaning === "function" ? cleanChoiceMeaning(wObj.m) : wObj.m;
          }
          arr.push(copy);
          mapByW.set(wLow, copy);
        }
      });
    });
  }

  // スクリプト評価時（0.000秒）に即座に実行！
  synchronizeAllVocabImmediately();

