    { label: "berapa 3兄弟（いくつ・いくつかの・どれほど）", words: ["berapa", "beberapa", "seberapa"] },
    { label: "標準語(rezeki) vs 口語・非標準綴り(rejeki)", words: ["rezeki", "rejeki", "nafkah"] },
    { label: "短編小説(cerpen) vs 連載小説(cerbung)", words: ["cerpen", "cerbung", "novelis"] },
    { label: "地平線・視野を表す重要類義語", words: ["ufuk", "cakrawala", "wawasan"] },
    { label: "スリムで引き締まった体型を表す類義語", words: ["langsing", "ramping", "kurus"] },
    { label: "生産者(produsen) vs 消費者(konsumen)", words: ["produsen", "konsumen"] },
    { label: "少し・やや(agak) vs どうやら〜らしい(agaknya)", words: ["agak", "agaknya", "rupanya"] },
    { label: "遅い(lambat) vs 遅刻する・手遅れ(terlambat) vs 速い(cepat)", words: ["lambat", "terlambat", "cepat"] }
