  // -------------------------------------------------------------------
  // 2. 0.000秒（同期フェーズ）で d.vocab に統合 ＆ index.html の内部DBを更新！
  // -------------------------------------------------------------------
  function syncV18StandardWords() {
    const arr = d.vocab;
    if (!Array.isArray(arr)) return;
    const mapByW = new Map();
    for (let i = 0; i < arr.length; i++) {
      if (arr[i] && arr[i].w) mapByW.set(arr[i].w.trim().toLowerCase(), arr[i]);
    }
    V18_STANDARD_WORDS.forEach(item => {
      const wl = item.w.trim().toLowerCase();
      if (mapByW.has(wl)) {
        Object.assign(mapByW.get(wl), item);
      } else {
        arr.push({ ...item });
        mapByW.set(wl, item);
      }
    });

    if (typeof window.__reloadWhatsIndo === "function") {
      try { window.__reloadWhatsIndo(); } catch (e) {}
    }
  }
  syncV18StandardWords();

