  // 2. 🚀 重複ロード遮断（差分検知ロック）＆ V35データの0.000秒同期
  // -------------------------------------------------------------------
  const arr = d.vocab;
  const mapByW = new Map();
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] && arr[i].w) mapByW.set(arr[i].w.trim().toLowerCase(), arr[i]);
  }
  V35_MILESTONE_6000_WORDS.forEach(item => {
    const wl = item.w.trim().toLowerCase();
    if (mapByW.has(wl)) {
      Object.assign(mapByW.get(wl), item);
    } else {
      arr.push({ ...item });
      mapByW.set(wl, item);
    }
  });

  // ★核心：index.html が定義する window.__reloadWhatsIndo をスマート・ロックで包み、
  //   過去のパッチ群から何十回呼ばれても、データ数が同じなら 0.0000ms で即スキップする！
  let rawReloadFn  = window.__reloadWhatsIndo || null;
  let lastBuildSig = "";

  function smartReloadGuard() {
    if (typeof rawReloadFn !== "function") return;
    const vLen = Array.isArray(d.vocab) ? d.vocab.length : 0;
    const aLen = Array.isArray(d.acro) ? d.acro.length : 0;
    const sLen = Array.isArray(d.singkatan) ? d.singkatan.length : 0;
    const sig  = `${vLen}:${aLen}:${sLen}`;
    if (sig === lastBuildSig) return; // すでに最新状態で構築済みなら即リターン（重複ループ100%遮断）
    lastBuildSig = sig;
    rawReloadFn();
  }

  try {
    Object.defineProperty(window, "__reloadWhatsIndo", {
      configurable: true,
      get: function() { return smartReloadGuard; },
      set: function(fn) {
        rawReloadFn  = fn;
        lastBuildSig = ""; // 新関数セット時は初回ビルドを許可
      }
    });
  } catch (e) {}

