  const arr = d.vocab;
  const mapByW = new Map();
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] && arr[i].w) mapByW.set(arr[i].w.trim().toLowerCase(), arr[i]);
  }
  V40_HIGH_FREQ_WORDS.forEach(item => {
    const wl = item.w.trim().toLowerCase();
    if (mapByW.has(wl)) {
      Object.assign(mapByW.get(wl), item);
    } else {
      arr.push({ ...item });
      mapByW.set(wl, item);
    }
  });

  function syncV40UI() {
    if (typeof window.__reloadWhatsIndo === "function") {
      try { window.__reloadWhatsIndo(); } catch (e) {}
    }

    const vSource = d.vocab;
    const aSource = Array.isArray(d.acro) ? d.acro : [];
    const vCatMap = window.__WI_V5_VCAT || new Map();
    const aCatMap = window.__WI_V5_ACAT || new Map();
    const counts  = {};

    vSource.forEach(item => {
      if (!item || !item.w) return;
      const wKey = item.w.trim().toLowerCase();
      const cat = item.topicCat || vCatMap.get(wKey) || "🏠 日常・生活・移動";
      item.topicCat = cat;
      vCatMap.set(wKey, cat);
      counts[cat] = (counts[cat] || 0) + 1;
    });
    aSource.forEach(item => {
      if (!item || !item.acro) return;
      const aKey = item.acro.trim().toLowerCase();
      const cat = item.topicCat || aCatMap.get(aKey) || "⚖️ 政治・法律・社会";
      item.topicCat = cat;
      aCatMap.set(aKey, cat);
      counts[cat] = (counts[cat] || 0) + 1;
    });

    const totalExact = vSource.length + aSource.length;
    const barV4 = document.getElementById("az-topic-bar-v4");
    if (barV4) {
      const labels = [
        `全分野 (${totalExact})`,
        `🏠 日常・生活・移動 (${counts["🏠 日常・生活・移動"] || 0})`,
        `🍽️ 食・料理 (${counts["🍽️ 食・料理"] || 0})`,
        `🏥 健康・身体・感情 (${counts["🏥 健康・身体・感情"] || 0})`,
        `🎓 教育・学術・IT (${counts["🎓 教育・学術・IT"] || 0})`,
        `💼 仕事・経済・買い物 (${counts["💼 仕事・経済・買い物"] || 0})`,
        `⚖️ 政治・法律・社会 (${counts["⚖️ 政治・法律・社会"] || 0})`,
        `🌿 自然・天気・動植物 (${counts["🌿 自然・天気・動植物"] || 0})`,
        `💬 スラング・口語 (${counts["💬 スラング・口語"] || 0})`
      ];
      barV4.querySelectorAll(".sub-filter-pill").forEach((btn, idx) => {
        if (labels[idx]) btn.textContent = labels[idx];
      });
    }
    const allLetterBtn = document.querySelector("#az-letter-bar .az-letter-btn");
    if (allLetterBtn && allLetterBtn.textContent.startsWith("ALL")) {
      allLetterBtn.textContent = `ALL (${totalExact})`;
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", syncV40UI);
  } else {
    syncV40UI();
  }
