/* =====================================================================
   WhatsIndo V56 関連語・類義語・同語幹チップ 100%即時ジャンプ復活パッチ
   1. プログラム内部の合成 input イベント（!e.isTrusted）に対する stopImmediatePropagation を無効化し、
      チップクリック時のジャンプ検索がデバウンスに遮断される現象を100%解消
   2. 辞書検索フィルタ実行時に「見出し語完全一致」を必ず先頭（0番目）へ配置し、
      短い単語（ia / kecil / hak / UMKM 等）や新規追加語も35件制限で漏れずに100%ジャンプ
   ===================================================================== */
(function() {
  // -------------------------------------------------------------------
  // 1. ★最重要：V53のデバウンスが「チップクリック時の内部ジャンプ通信（!e.isTrusted）」を
  //    止めてしまわないよう、合成 input イベントの伝播遮断をガード！
  // -------------------------------------------------------------------
  const dIn  = document.getElementById("dict-input");
  const azIn = document.getElementById("az-filter-input");
  if (dIn)  dIn.__v53Debounced  = true;
  if (azIn) azIn.__v53Debounced = true;

  const origStopImmediate = Event.prototype.stopImmediatePropagation;
  Event.prototype.stopImmediatePropagation = function() {
    // 関連語・類義語チップを押した時のプログラム合成イベント（!this.isTrusted）は絶対に止めない！
    if (this && this.type === "input" && !this.isTrusted) {
      return;
    }
    return origStopImmediate.apply(this, arguments);
  };

  // -------------------------------------------------------------------
  // 2. renderDict() の検索結果で「見出し語が完全一致する単語」を必ず先頭（index 0）に配置！
  //    （これにより kecil や usaha のようなヒット数が多い単語でも .slice(0, 35) で絶対に漏れない）
  // -------------------------------------------------------------------
  const prevFilter = Array.prototype.filter;
  Array.prototype.filter = function(callback, thisArg) {
    const res = prevFilter.call(this, callback, thisArg);

    if (
      res.length > 1 &&
      this.length > 1000 &&
      typeof callback === "function" &&
      this[0] && typeof this[0] === "object" && "w" in this[0]
    ) {
      const fnStr = Function.prototype.toString.call(callback);
      // index.html の renderDict() 内のフィルタ呼び出しを検出
      if (fnStr.indexOf("v.fullM") !== -1 && fnStr.indexOf("state.azPos") === -1) {
        const inp = document.getElementById("dict-input");
        const q = inp ? inp.value.trim().toLowerCase() : "";
        if (q) {
          let exactIdx = -1;
          for (let i = 0; i < res.length; i++) {
            if (res[i] && res[i].w && res[i].w.trim().toLowerCase() === q) {
              exactIdx = i;
              break;
            }
          }
          // 完全一致する見出し語があれば配列の一番先頭（0番目）へ移動
          if (exactIdx > 0) {
            const exactItem = res.splice(exactIdx, 1)[0];
            res.unshift(exactItem);
          }
        }
      }
    }
    return res;
  };
})();
