  // -------------------------------------------------------------------
  // 3. 既存配列のインプレース更新 ＆ 「daya」を先頭へ配置（関連語ファミリーで1番目に表示）
  // -------------------------------------------------------------------
  const vCatMap = window.__WI_V5_VCAT || new Map();
  window.__WI_V5_VCAT = vCatMap;

  UPGRADED_VOCAB_ITEMS.forEach(function(item) {
    const wl = item.w.trim().toLowerCase();
    if (item.topicCat) {
      item.__lockedCat = item.topicCat;
      vCatMap.set(wl, item.topicCat);
    }

    const matchedIndices = [];
    for (let i = 0; i < d.vocab.length; i++) {
      const cur = d.vocab[i];
      if (cur && cur.w && cur.w.trim().toLowerCase() === wl) {
        matchedIndices.push(i);
      }
    }

    if (matchedIndices.length > 0) {
      const targetObj = d.vocab[matchedIndices[0]];
      Object.assign(targetObj, item);
      for (let j = matchedIndices.length - 1; j >= 1; j--) {
        d.vocab.splice(matchedIndices[j], 1);
      }
      // 「daya」は同じ語幹ファミリーの一番先頭に必ず表示されるよう配列の先頭へ移動
      if (wl === "daya") {
        const curIdx = d.vocab.indexOf(targetObj);
        if (curIdx > 0) {
          d.vocab.splice(curIdx, 1);
          d.vocab.unshift(targetObj);
        }
      }
    } else {
      if (wl === "daya") {
        d.vocab.unshift(item);
      } else {
        d.vocab.push(item);
      }
    }
  });

  // localStorage 内のスター問題や復習問題に menggunduli の旧例文が残っていた場合も最新例文へ自動同期
  ["wi_wrongs_v2", "wi_stars_v2"].forEach(function(storageKey) {
    try {
      const list = JSON.parse(localStorage.getItem(storageKey) || "[]");
      let changed = false;
      for (let i = 0; i < list.length; i++) {
        const it = list[i];
        if (!it || !it.id) continue;
        if (String(it.id).toLowerCase().endsWith("::menggunduli")) {
          const gItem = UPGRADED_VOCAB_ITEMS[1];
          it.ttsSentence = gItem.ex;
          it.summaryHead = `${gItem.w} [語幹: ${gItem.r}] ＝ ${gItem.m}`;
          it.summarySent = `${gItem.ex}\n${gItem.tr}`;
          changed = true;
        }
      }
      if (changed) {
        localStorage.setItem(storageKey, JSON.stringify(list));
      }
    } catch (e) {}
  });

