/* =====================================================================
   WhatsIndo ピンポイント修正パッチ
   1. 左上の重複「排除リスト」ボタンを1個だけに完全統一
   2. 単語ラッシュモード中の「スペースキー」「右矢印キー(→)」「Enterキー」を完全無効化し、
      120秒ラッシュや他モードへ勝手に切り替わるバグを100%遮断
   ===================================================================== */
(function() {
  // -------------------------------------------------------------------
  // 1. 重複している古い「排除リスト」ボタン (#btn-exclude-list-top) を完全消去し1個に統一
  // -------------------------------------------------------------------
  if (!document.getElementById("wi-fix-single-exclude-btn-style")) {
    const st = document.createElement("style");
    st.id = "wi-fix-single-exclude-btn-style";
    st.textContent = `
      #btn-exclude-list-top { display: none !important; }
    `;
    document.head.appendChild(st);
  }

  function removeDuplicateExcludeButtons() {
    // 古いIDのボタンがあれば削除
    document.querySelectorAll("#btn-exclude-list-top").forEach(function(btn) {
      btn.remove();
    });
    // 万が一 #btn-exclude-list-top-v2 が複数あった場合も先頭1個だけ残す
    const v2Btns = document.querySelectorAll("#btn-exclude-list-top-v2");
    for (let i = 1; i < v2Btns.length; i++) {
      v2Btns[i].remove();
    }
  }

  removeDuplicateExcludeButtons();
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function() {
      removeDuplicateExcludeButtons();
      setTimeout(removeDuplicateExcludeButtons, 60);
      setTimeout(removeDuplicateExcludeButtons, 250);
    });
  } else {
    setTimeout(removeDuplicateExcludeButtons, 60);
    setTimeout(removeDuplicateExcludeButtons, 250);
  }

  // -------------------------------------------------------------------
  // 2. 単語ラッシュモード中の Space / ArrowRight(→) / Enter 完全ロック
  // -------------------------------------------------------------------
  function isWordRushModeActiveNow() {
    const hdrName = document.getElementById("hdr-name");
    if (hdrName && hdrName.textContent.trim() === "単語ラッシュモード") return true;
    const area = document.getElementById("chat-messages-area");
    if (area && area.querySelector(".wr-stage-wrap, .wr-setup-card")) return true;
    return false;
  }

  function blockKeyEventCompletely(e) {
    e.preventDefault();
    e.__wiAllowFinalStop = true;
    e.__wiMasterFinalStop = true;
    if (typeof e.stopImmediatePropagation === "function") {
      e.stopImmediatePropagation();
    }
    e.stopPropagation();
  }

  // keydown / keyup / keypress のすべてで Space・右矢印・左矢印・Enter を最上流で完全遮断
  ["keydown", "keyup", "keypress"].forEach(function(evType) {
    window.addEventListener(evType, function(e) {
      if (!isWordRushModeActiveNow()) return;

      // 辞書モーダル・設定・単語帳・排除リストモーダルが開いている時は除外
      const openModal = document.querySelector(".modal-overlay.open");
      if (openModal) return;

      // 検索窓に文字入力している時は除外
      const activeEl = document.activeElement;
      if (activeEl && activeEl.id === "dict-input") return;

      const key  = e.key || "";
      const code = e.code || "";

      // ★単語ラッシュ中はスペースキー・右矢印キー・左矢印キー・Enterキー・Hキーを完全無効化！
      if (
        key === " " ||
        code === "Space" ||
        key === "ArrowRight" ||
        key === "ArrowLeft" ||
        key === "Enter" ||
        key.toLowerCase() === "h"
      ) {
        if (activeEl && activeEl.tagName === "BUTTON") {
          activeEl.blur();
        }
        blockKeyEventCompletely(e);
        return;
      }

      // 単語ラッシュプレイ中の数字キー 1〜6 回答を確実に動作させる
      if (evType === "keydown" && /^[1-6]$/.test(key)) {
        const stageHud = document.getElementById("wr-stage-hud");
        if (stageHud) {
          const idx = parseInt(key, 10) - 1;
          const cards = document.querySelectorAll("#wa-choices-grid .wa-choice-card");
          if (cards[idx] && !cards[idx].disabled) {
            blockKeyEventCompletely(e);
            cards[idx].click();
            if (document.activeElement && document.activeElement.tagName === "BUTTON") {
              document.activeElement.blur();
            }
          }
        }
      }
    }, true);
  });

  // 単語ラッシュモードに切り替わった瞬間、左サイドバー等のボタンに残っているフォーカスを自動で外す（スペースキー誤爆防止）
  document.addEventListener("click", function() {
    if (isWordRushModeActiveNow()) {
      const activeEl = document.activeElement;
      if (activeEl && activeEl.tagName === "BUTTON") {
        setTimeout(function() {
          if (isWordRushModeActiveNow() && document.activeElement === activeEl) {
            activeEl.blur();
          }
        }, 10);
      }
    }
  }, true);
})();
