  Object.keys(UPGRADED_ENTRIES_MAP).forEach(function(wl) {
    if (!updatedKeys.has(wl)) {
      const item = UPGRADED_ENTRIES_MAP[wl];
      vCatMap.set(wl, item.topicCat || "🏠 日常・生活・移動");
      prevPush.call(d.vocab, item);
    }
  });

